def transform(grid):
    # Four stacked 3-row layers: the top layer has priority, then each lower layer.
    height = len(grid)
    width = len(grid[0])
    layers = [grid[i:i + 3] for i in range(0, height, 3)]
    out = []
    for r in range(3):
        row = []
        for c in range(width):
            value = 0
            for layer in reversed(layers):
                if layer[r][c] != 0:
                    value = layer[r][c]
            row.append(value)
        out.append(row)
    return out

